import{_ as d,o as e,c as r,a5 as a}from"./chunks/framework.bIR-4glx.js";const p=JSON.parse('{"title":"英语能力诊断：四项基线与迁移记录","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/english-diagnostic.zh.md","filePath":"public/downloads/worksheets/english-diagnostic.zh.md","lastUpdated":1795488252000}'),h={name:"public/downloads/worksheets/english-diagnostic.zh.md"};function i(l,t,n,o,s,b){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="英语能力诊断-四项基线与迁移记录" tabindex="-1">英语能力诊断：四项基线与迁移记录 <a class="header-anchor" href="#英语能力诊断-四项基线与迁移记录" aria-label="Permalink to &quot;英语能力诊断：四项基线与迁移记录&quot;">​</a></h1><p>这是完整的四项诊断工作表，不是五分钟起步任务，也不是一次把人钉在 A1-C2 上的考试。只想先开始时，去<a href="https://byoungd.github.io/up/topics/english-diagnostic" target="_blank" rel="noreferrer">英语诊断入口</a>任选一项完成五分钟单项基线。需要整体诊断时，选一个真实主题，在相近时间和明确限制下完成听、读、说、写的首版；保存原始样本，分别记录障碍，七天后撤掉最近提示做平行任务，三十天后重复一项真实交付。</p><p>把这张卡复制到私有笔记中。不要写入密码、客户资料、证件、医疗隐私、未授权的第三方内容或禁止记录的考试材料。</p><h2 id="_1-先定义诊断边界" tabindex="-1">1. 先定义诊断边界 <a class="header-anchor" href="#_1-先定义诊断边界" aria-label="Permalink to &quot;1. 先定义诊断边界&quot;">​</a></h2><h3 id="english-diagnostic-yyyy-mm-dd" tabindex="-1">English Diagnostic - YYYY-MM-DD <a class="header-anchor" href="#english-diagnostic-yyyy-mm-dd" aria-label="Permalink to &quot;English Diagnostic - YYYY-MM-DD&quot;">​</a></h3><p>真实场景：工作 / 学习 / 求职 / 生活 / 其他<br> 真实主题：<br> 目标受众或对话对象：<br> 四项共同的最小交付：<br> 诊断开始/结束日期：<br> 材料、版本与来源：<br> 共同限制（时间、设备、环境）：<br> 允许的词典 / 字幕 / 翻译 / 搜索 / AI / 人工帮助：<br> 隐私、版权、考试、专业责任边界：<br> 第 7 天平行任务日期：<br> 第 30 天复测日期：<br> 第 12 周真实任务日期：</p><p>四项不必使用完全同一种材料，但要让主题、难度、时间和完成标准可比较。若真实目标是岗位，不要让一个综合等级替代岗位描述中的具体语言动作。</p><h2 id="_2-四项首版任务" tabindex="-1">2. 四项首版任务 <a class="header-anchor" href="#_2-四项首版任务" aria-label="Permalink to &quot;2. 四项首版任务&quot;">​</a></h2><p>第一版尽量不查词、不让 AI 代写或代答。先完成，再标出哪里需要帮助。</p><table tabindex="0"><thead><tr><th>能力</th><th>建议首版</th><th>最低交付</th></tr></thead><tbody><tr><td>听力</td><td>听 2-4 分钟真实音频一次</td><td>写主旨、3 个确定细节、责任/下一步并复述 60 秒</td></tr><tr><td>阅读</td><td>读 600-1000 词真实文本</td><td>写五句主线、一个证据位置、一个质疑或未知</td></tr><tr><td>口语</td><td>不看稿录 2 分钟解释、经历或流程</td><td>听众能复述目的、关键事实和下一步</td></tr><tr><td>写作</td><td>20 分钟完成 180-250 词邮件、说明或短文</td><td>受众知道结论、依据、限制和行动</td></tr></tbody></table><p>不要为了让四项“公平”而削掉真实任务的差异。诊断要显示能力在哪些条件下工作，而不是制造一张漂亮的平均表。</p><h2 id="_2a-按需记录协作维度" tabindex="-1">2A. 按需记录协作维度 <a class="header-anchor" href="#_2a-按需记录协作维度" aria-label="Permalink to &quot;2A. 按需记录协作维度&quot;">​</a></h2><p>如果你的目标包含远程协作、客户沟通、课堂讨论或家庭学习，再补做下面的任务。它们不是新的等级，也不必每次都测；只在现实中确实影响结果时保存证据。</p><table tabindex="0"><thead><tr><th>任务维度</th><th>10–15 分钟样本</th><th>证据位置与结果</th></tr></thead><tbody><tr><td>转述与调解</td><td>读两段立场不同的短材料，说明各自主张、差异和未知</td><td>听众能分清原文、你的转述和你的推断；</td></tr><tr><td>在线互动</td><td>写一条进展、一项阻塞和下一步，让对方无需开会也能继续</td><td>对方知道负责人、时间和缺失信息；</td></tr><tr><td>误解修复</td><td>请求澄清，再复述共识与未决问题</td><td>对方确认复述准确，下一步没有因猜测改变；</td></tr></tbody></table><p>若其中一项是高风险环节，不要用口语或写作分数替代它。把样本、听众反馈和下一次平行任务一起保存。</p><h2 id="_3-保存首版与条件" tabindex="-1">3. 保存首版与条件 <a class="header-anchor" href="#_3-保存首版与条件" aria-label="Permalink to &quot;3. 保存首版与条件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>首版位置</th><th>开始/结束</th><th>工具与提示</th><th>完成/未完成</th><th>我最不确定什么</th></tr></thead><tbody><tr><td>听力</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>阅读</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>口语</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>写作</td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>首版之后我仍能独立说明的内容：<br> 如果重做，我最想改变的条件：<br> 不能从首版推出的结论：</p><h2 id="_4-按影响评分-不按感觉评分" tabindex="-1">4. 按影响评分，不按感觉评分 <a class="header-anchor" href="#_4-按影响评分-不按感觉评分" aria-label="Permalink to &quot;4. 按影响评分，不按感觉评分&quot;">​</a></h2><p>每项 <code>0-2</code> 分：<code>0=没有证据或未完成</code>，<code>1=部分完成、依赖提示或不稳定</code>，<code>2=在当前条件下独立完成</code>。每个分数都写证据位置。</p><table tabindex="0"><thead><tr><th>能力</th><th style="text-align:right;">任务完成</th><th style="text-align:right;">可理解度</th><th style="text-align:right;">准确与范围</th><th style="text-align:right;">组织/流畅</th><th style="text-align:right;">独立与迁移</th><th>证据理由</th></tr></thead><tbody><tr><td>听力</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>阅读</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>口语</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>写作</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr></tbody></table><h3 id="分数解释" tabindex="-1">分数解释 <a class="header-anchor" href="#分数解释" aria-label="Permalink to &quot;分数解释&quot;">​</a></h3><ul><li><strong>任务完成</strong>：信息和意图是否到达，动作是否能继续；</li><li><strong>可理解度</strong>：真实读者/听众是否无需过度猜测；</li><li><strong>准确与范围</strong>：词汇、语法、发音、拼写和细节是否支持任务；</li><li><strong>组织/流畅</strong>：结构、顺序、停顿或版面是否妨碍使用；</li><li><strong>独立与迁移</strong>：撤掉最近提示、改变一个条件后能否再次完成。</li></ul><p>总分只用于同一个人的纵向比较，不是人格、智力或录用资格。CEFR 方向请结合<a href="https://byoungd.github.io/up/threads/part-1/0-cefr" target="_blank" rel="noreferrer">CEFR 目标与英语能力自测</a>，不要把一次诊断写成永久等级。</p><h2 id="_5-为每项只选一个首要障碍" tabindex="-1">5. 为每项只选一个首要障碍 <a class="header-anchor" href="#_5-为每项只选一个首要障碍" aria-label="Permalink to &quot;5. 为每项只选一个首要障碍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>首要障碍</th><th>样本/时间段</th><th>任务影响</th><th>下一项最小修复</th><th>对应证据卡</th></tr></thead><tbody><tr><td>听力</td><td>词汇 / 声音 / 句法 / 背景 / 注意 / 设备</td><td></td><td></td><td></td><td><a href="https://byoungd.github.io/up/templates/listening-audit" target="_blank" rel="noreferrer">听力证据卡</a></td></tr><tr><td>阅读</td><td>词汇 / 结构 / 背景 / 证据 / 版面 / 容量</td><td></td><td></td><td></td><td><a href="https://byoungd.github.io/up/templates/reading-evidence" target="_blank" rel="noreferrer">阅读证据卡</a></td></tr><tr><td>口语</td><td>词块 / 发音 / 组织 / 互动 / 语域 / 追问</td><td></td><td></td><td></td><td><a href="https://byoungd.github.io/up/templates/speaking-evidence" target="_blank" rel="noreferrer">口语证据卡</a></td></tr><tr><td>写作</td><td>任务 / 事实 / 结构 / 句子 / 语域 / 交付</td><td></td><td></td><td></td><td><a href="https://byoungd.github.io/up/templates/writing-evidence" target="_blank" rel="noreferrer">写作证据卡</a></td></tr></tbody></table><p>若一个障碍无法指出样本或时间段，先不要把它当作结论。一个人可以“知道很多词”却在听力切分上失败，也可以语法准确却无法组织异步交接。</p><h2 id="_6-设计一次定向修复" tabindex="-1">6. 设计一次定向修复 <a class="header-anchor" href="#_6-设计一次定向修复" aria-label="Permalink to &quot;6. 设计一次定向修复&quot;">​</a></h2><p>我只要修复的一个障碍：<br> 修复动作（25-45 分钟）：<br> 材料与来源：<br> 允许的最小支架：<br> 完成标准：<br> 我要保存的前后样本：<br> 哪条反馈会让我改变方案：</p><p>顺序通常是：先保证意思和任务完成，再修事实与结构，之后处理高影响词汇、语法、发音或写作语域，最后才做不改变结果的风格细节。</p><h2 id="_7-延迟复测与迁移" tabindex="-1">7. 延迟复测与迁移 <a class="header-anchor" href="#_7-延迟复测与迁移" aria-label="Permalink to &quot;7. 延迟复测与迁移&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间</th><th>撤掉什么</th><th>改变什么</th><th>输出</th><th>结果/证据</th></tr></thead><tbody><tr><td>第 1 天</td><td>首版之后的答案</td><td>原条件</td><td>修复版</td><td></td></tr><tr><td>第 7 天</td><td>最近提示和旧句</td><td>平行主题或受众</td><td>同类任务</td><td></td></tr><tr><td>第 30 天</td><td>工具对话和批注</td><td>真实材料或时间压力</td><td>一项真实交付</td><td></td></tr><tr><td>第 12 周</td><td>旧任务与旧评分</td><td>目标岗位/课程/生活场景</td><td>完整任务</td><td></td></tr></tbody></table><p>第 7 天仍然能独立完成：<br> 第 30 天仍然反复的错误：<br> 哪一项只在熟悉主题成功：<br> 四项能力中最值得增加时间的地方：<br> 我不能从这次复测推出什么：</p><h2 id="_8-记录-ai、翻译和人工反馈" tabindex="-1">8. 记录 AI、翻译和人工反馈 <a class="header-anchor" href="#_8-记录-ai、翻译和人工反馈" aria-label="Permalink to &quot;8. 记录 AI、翻译和人工反馈&quot;">​</a></h2><p>工具 / 模型 / 版本与日期：<br> 工具介入前的样本位置：<br> 它只做了什么：诊断 / 追问 / 反例 / 转写 / 反馈 / 其他<br> 它生成或改写的范围：<br> 我用什么一手来源、词典、教师、同伴或真实受众核验：<br> 我采纳、拒绝或延后的建议及理由：<br> 关闭工具后的独立样本：<br> 按学校、客户、雇主或考试规则需要怎样披露：</p><p>模型答案、语音识别分数和润色终稿都不能单独证明能力。重要判断必须回到原始材料、实际回应和具名责任人。</p><h2 id="_9-形成下一周期决定" tabindex="-1">9. 形成下一周期决定 <a class="header-anchor" href="#_9-形成下一周期决定" aria-label="Permalink to &quot;9. 形成下一周期决定&quot;">​</a></h2><p>当前分项方向（不是永久等级）：<br> 最强的真实证据：<br> 最弱且最影响生活的证据：<br> 继续：<br> 降档：<br> 换变量：<br> 暂停或求助：<br> 下一项最小任务：<br> 下一次复查日期：</p><p>相关入口：<a href="https://byoungd.github.io/up/threads/part-1/1-understanding" target="_blank" rel="noreferrer">认知篇：把努力变成可验证的学习</a> ｜ <a href="https://byoungd.github.io/up/templates/vocabulary-audit" target="_blank" rel="noreferrer">词汇证据卡</a> ｜ <a href="https://byoungd.github.io/up/templates/grammar-evidence" target="_blank" rel="noreferrer">语法证据卡</a> ｜ <a href="https://byoungd.github.io/up/templates/listening-audit" target="_blank" rel="noreferrer">听力证据卡</a> ｜ <a href="https://byoungd.github.io/up/templates/reading-evidence" target="_blank" rel="noreferrer">阅读证据卡</a> ｜ <a href="https://byoungd.github.io/up/templates/speaking-evidence" target="_blank" rel="noreferrer">口语证据卡</a> ｜ <a href="https://byoungd.github.io/up/templates/writing-evidence" target="_blank" rel="noreferrer">写作证据卡</a> ｜ <a href="https://byoungd.github.io/up/templates/evidence-chain" target="_blank" rel="noreferrer">证据链模板</a></p><hr><p>来源：<a href="https://byoungd.github.io/up/templates/english-diagnostic" target="_blank" rel="noreferrer">人生进阶指南</a> · 稿件更新：2026-10-19。内容许可：<a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>。</p>',41)])])}const u=d(h,[["render",i]]);export{p as __pageData,u as default};
